//! The CJK codec tables, generated by `tools/gen_cjk.py` from the
//! pinned source's `Modules/cjkcodecs/mappings_*.h` (spec section
//! 10.6): the flat value arrays and the per-first-byte index arrays
//! CPython's `_codecs_*` modules compile against, sentinels verbatim.
//!
//! The index triples are CPython's `(map + offset, bottom, top)` rows
//! with the null rows rewritten to `bottom > top`.

pub mod cn;
pub mod hk;
pub mod jp;
pub mod kr;
pub mod tw;

/// `UNIINV`: a decode table's unassigned cell (`U` in the mapping
/// headers); `TRYMAP_DEC` rejects exactly this value.
pub const UNIINV: u16 = 0xFFFE;
/// `NOCHAR`: an encode table's unmapped cell (`N`); `TRYMAP_ENC`
/// rejects exactly this value.
pub const NOCHAR: u16 = 0xFFFF;
/// `MULTIC`: an encode cell whose character needs the following
/// character too (`M`), for JIS X 0213 and HKSCS pairs.
pub const MULTIC: u16 = 0xFFFE;
/// `DBCINV`: `find_pairencmap`'s not-found marker (`D`).
pub const DBCINV: u16 = 0xFFFD;

/// A `struct dbcs_index` table: byte pairs to code points. `index`
/// holds CPython's `(offset, bottom, top)` per first byte; the offset
/// indexes `data` and `bottom..=top` is the second byte's range.
pub struct DecMap {
    pub data: &'static [u16],
    pub index: &'static [(u32, u16, u16); 256],
}

/// A `struct unim_index` table: code points to byte pairs, bucketed by
/// the code point's high byte.
pub struct EncMap {
    pub data: &'static [u16],
    pub index: &'static [(u32, u16, u16); 256],
}

/// A `struct widedbcs_index` table: byte pairs to wide values (the JIS
/// X 0213 pair decodes, two code points packed per cell).
pub struct WideDecMap {
    pub data: &'static [u32],
    pub index: &'static [(u32, u16, u16); 256],
}

/// A `struct pair_encodemap` table: packed two-code-point sequences to
/// byte pairs, sorted for the binary search `find_pairencmap` runs.
pub struct PairEncMap {
    pub pairs: &'static [(u32, u16)],
}

/// `_TRYMAP_DEC`: the code point of `(c1, c2)`, or `None` for a null
/// row, an out-of-range second byte or an `UNIINV` cell.
pub fn trymap_dec(map: &DecMap, c1: u8, c2: u8) -> Option<u32> {
    let (offset, bottom, top) = map.index[c1 as usize];
    if bottom > top {
        return None;
    }
    let c2 = c2 as u16;
    if c2 < bottom || c2 > top {
        return None;
    }
    let value = map.data[offset as usize + (c2 - bottom) as usize];
    if value != UNIINV {
        Some(value as u32)
    } else {
        None
    }
}

/// `_TRYMAP_ENC`: the byte pair of `uni`, or `None` for a null bucket,
/// an out-of-range low byte or a `NOCHAR` cell.
pub fn trymap_enc(map: &EncMap, uni: u32) -> Option<u16> {
    if uni > 0xFFFF {
        return None;
    }
    let (offset, bottom, top) = map.index[(uni >> 8) as usize];
    if bottom > top {
        return None;
    }
    let low = (uni & 0xFF) as u16;
    if low < bottom || low > top {
        return None;
    }
    let value = map.data[offset as usize + (low - bottom) as usize];
    if value != NOCHAR { Some(value) } else { None }
}

/// `trymap_dec` over a `WideDecMap`. The sentinel test is the same
/// `!= UNIINV` every `_TRYMAP_DEC` runs, so the pair table's `M` cells
/// (0xFFFE, marking compositions handled elsewhere) fail here exactly
/// as they do in CPython.
pub fn trymap_wide_dec(map: &WideDecMap, c1: u8, c2: u8) -> Option<u32> {
    let (offset, bottom, top) = map.index[c1 as usize];
    if bottom > top {
        return None;
    }
    let c2 = c2 as u16;
    if c2 < bottom || c2 > top {
        return None;
    }
    let value = map.data[offset as usize + (c2 - bottom) as usize];
    if value != UNIINV as u32 {
        Some(value)
    } else {
        None
    }
}

/// `find_pairencmap`: the code of the packed `(body, modifier)`
/// sequence, or `None` (`DBCINV`) when the table holds no such row.
pub fn find_pairencmap(body: u32, modifier: u32, map: &PairEncMap) -> Option<u16> {
    let value = (body << 16) | modifier;
    match map.pairs.binary_search_by(|&(uni, _)| uni.cmp(&value)) {
        Ok(index) => Some(map.pairs[index].1),
        Err(_) => None,
    }
}
